 40	        return "&#39;";
 41	      default:
 42	        return character;
 43	    }
 44	  });
 45	}
 46	
 47	function getSurvivalTone({ healthPercent, poisonActive, warningActive }) {
 48	  if (healthPercent <= 35) {
 49	    return { tone: "critical", label: "Critical" };
 50	  }
 51	
 52	  if (warningActive) {
 53	    return { tone: "danger", label: "Brace" };
 54	  }
 55	
 56	  if (poisonActive || healthPercent <= 60) {
 57	    return { tone: "warning", label: "Watch" };
 58	  }
 59	
 60	  return { tone: "stable", label: "Stable" };
 61	}
 62	
 63	export function renderHud(root, state = sampleState) {
 64	  const health = Math.max(0, Math.round(toFiniteNumber(state.health)));
 65	  const stamina = Math.max(0, Math.round(toFiniteNumber(state.stamina)));
 66	  const poisonSeconds = Math.max(0, Math.round(toFiniteNumber(state.poisonSeconds)));
 67	  const healthPercent = clampPercent(health);
 68	  const staminaPercent = clampPercent(stamina);
 69	  const poisonActive = poisonSeconds > 0;
 70	  const warning = String(state.warning ?? "").trim();
 71	  const pickup = String(state.pickup ?? "").trim();
 72	  const quest = String(state.quest ?? "").trim() || "Stay alive";
 73	  const survivalTone = getSurvivalTone({
 74	    healthPercent,
 75	    poisonActive,
 76	    warningActive: Boolean(warning),
 77	  });
 78	  const staminaLabel = staminaPercent <= 30 ? "Recover" : "Ready";
 79	
 80	  root.innerHTML = `
 81	    <section class="hud" aria-label="tactical HUD">
 82	      <div class="hud-rack" aria-label="player status">
 83	        <section class="hud-card hud-card--health" data-tone="${survivalTone.tone}">
 84	          <div class="hud-card__eyebrow">
 85	            <span class="hud-card__label">Health</span>
 86	            <span class="hud-card__state">${survivalTone.label}</span>
 87	          </div>
 88	          <div class="hud-card__numbers">
 89	            <strong class="hud-card__value">${health}</strong>
 90	            <span class="hud-card__unit">/100 HP</span>
 91	          </div>
 92	          <div class="hud-meter hud-meter--health" aria-hidden="true">
 93	            <span style="width: ${healthPercent}%;"></span>
 94	          </div>
 95	          ${
 96	            poisonActive
 97	              ? `<div class="hud-card__status"><span class="hud-pill hud-pill--poison">Poison ${poisonSeconds}s</span></div>`
 98	              : ""
 99	          }
100	        </section>
101	
102	        <section class="hud-card hud-card--stamina" data-tone="${staminaLabel === "Recover" ? "warning" : "stable"}">
103	          <div class="hud-card__eyebrow">
104	            <span class="hud-card__label">Stamina</span>
105	            <span class="hud-card__state">${staminaLabel}</span>
106	          </div>
107	          <div class="hud-card__numbers">
108	            <strong class="hud-card__value">${stamina}</strong>
109	            <span class="hud-card__unit">/100 STA</span>
110	          </div>
111	          <div class="hud-meter hud-meter--stamina" aria-hidden="true">
112	            <span style="width: ${staminaPercent}%;"></span>
113	          </div>
114	        </section>
115	      </div>
116	
117	      <section class="hud-objective" aria-label="current objective">
118	        <span class="hud-objective__label">Objective</span>
119	        <strong class="hud-objective__text">${escapeHtml(quest)}</strong>
120	      </section>
121	
122	      ${
123	        pickup
124	          ? `
125	            <aside class="hud-ping" aria-live="polite">
126	              <span class="hud-ping__label">Nearby</span>
127	              <strong class="hud-ping__value">${escapeHtml(pickup)}</strong>
128	            </aside>
129	          `
130	          : ""
131	      }
132	
133	      ${
134	        warning
135	          ? `
136	            <section class="hud-alert" role="alert" aria-live="assertive">
137	              <span class="hud-alert__label">Danger</span>
138	              <strong class="hud-alert__text">${escapeHtml(warning)}</strong>
139	            </section>
140	          `
141	          : ""
142	      }
143	    </section>
144	  `;
145	}
146	
147	if (typeof document !== "undefined") {
148	  const root = document.querySelector("#hud-root");
149	  if (root) {
150	    renderHud(root);
151	  }
152	}

